package com.jnapanam.sportszone.tournament.model;import com.jnapanam.sportszone.identity.model.User;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="organizer_applications")public class OrganizerApplication{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private User user;@Column(name="organization_name",nullable=false,length=160)private String organizationName;@Column(columnDefinition="TEXT")private String experience;@Column(name="contact_number",nullable=false,length=20)private String contactNumber;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private OrganizerStatus status;@Column(name="review_note",length=300)private String reviewNote;@Column(name="applied_at",nullable=false)private Instant appliedAt;@Column(name="reviewed_at")private Instant reviewedAt;protected OrganizerApplication(){}public OrganizerApplication(User u,String o,String e,String c){id=UUID.randomUUID();user=u;organizationName=o.trim();experience=clean(e);contactNumber=c.trim();status=OrganizerStatus.PENDING;appliedAt=Instant.now();}public void review(OrganizerStatus s,String n){status=s;reviewNote=clean(n);reviewedAt=Instant.now();}public UUID getId(){return id;}public User getUser(){return user;}public String getOrganizationName(){return organizationName;}public String getExperience(){return experience;}public String getContactNumber(){return contactNumber;}public OrganizerStatus getStatus(){return status;}public String getReviewNote(){return reviewNote;}public Instant getAppliedAt(){return appliedAt;}private static String clean(String v){return v==null||v.isBlank()?null:v.trim();}}
